func croatianMonthName(month int) string {
	names := [...]string{
		"Siječanj", "Veljača", "Ožujak", "Travanj", "Svibanj", "Lipanj",
		"Srpanj", "Kolovoz", "Rujan", "Listopad", "Studeni", "Prosinac",
	}
	if month < 1 || month > 12 {
		return ""
	}
	return names[month-1]
}

